<script setup lang="ts">
import {computed,ref} from 'vue'
import {Minus,Plus} from 'lucide-vue-next'
import {useHysRootAttrs} from '../../config'
const props=withDefaults(defineProps<{modelValue:number;min?:number;max?:number;step?:number;precision?:number;stepStrictly?:boolean;disabled?:boolean;readonly?:boolean;ariaLabel?:string;showControls?:boolean;selectOnFocus?:boolean;size?:'sm'|'md'|'lg'}>(),{step:1,showControls:true,selectOnFocus:false,size:'md'})
const emit=defineEmits<{'update:modelValue':[value:number];change:[value:number];input:[value:number|null];focus:[event:FocusEvent];blur:[event:FocusEvent]}>(),hysRootAttrs=useHysRootAttrs(),input=ref<HTMLInputElement>()
const step=computed(()=>Number.isFinite(props.step)&&props.step!==0?Math.abs(props.step):1),digits=(n:number)=>{const [mantissa,exponent='0']=String(n).toLowerCase().split('e');return Math.max(0,(mantissa.split('.')[1]||'').length-Number(exponent))}
function normalize(value:number){let next=Number.isFinite(value)?value:0;if(props.stepStrictly)next=Math.round(next/step.value)*step.value;next=Math.min(props.max??Infinity,Math.max(props.min??-Infinity,next));return Number(next.toFixed(Math.min(12,Math.max(0,props.precision??Math.max(digits(step.value),digits(props.modelValue),digits(next))))))}
function update(value:number){if(props.disabled||props.readonly)return;const next=normalize(value);if(next!==props.modelValue){emit('update:modelValue',next);emit('change',next)}else if(input.value)input.value.value=String(next)}
function draft(event:Event){if(props.disabled||props.readonly)return;const field=event.target as HTMLInputElement;emit('input',field.value!==''&&Number.isFinite(field.valueAsNumber)?field.valueAsNumber:null)}
function keyboard(event:KeyboardEvent){if(event.key==='ArrowUp'||event.key==='ArrowDown'){event.preventDefault();update(props.modelValue+(event.key==='ArrowUp'?step.value:-step.value))}else if(event.key==='Home'&&props.min!==undefined){event.preventDefault();update(props.min)}else if(event.key==='End'&&props.max!==undefined){event.preventDefault();update(props.max)}}
defineExpose({focus:()=>input.value?.focus(),blur:()=>input.value?.blur(),select:()=>input.value?.select()})
</script>
<template><div v-bind="hysRootAttrs" class="hys-ui-ex-number" :class="[{'hys-ui-ex-number-disabled':disabled},'hys-ui-number-'+size]"><button v-if="showControls" type="button" aria-label="减少" :disabled="disabled||readonly||(min!==undefined&&modelValue<=min)" @click="update(modelValue-step)"><Minus :size="16"/></button><input ref="input" type="number" :aria-label="ariaLabel||'数值'" :value="modelValue" :min="min" :max="max" :step="step" :disabled="disabled" :readonly="readonly" @focus="selectOnFocus&&input?.select();emit('focus',$event)" @blur="emit('blur',$event)" @keydown="keyboard" @input="draft" @change="update(Number(($event.target as HTMLInputElement).value))"/><button v-if="showControls" type="button" aria-label="增加" :disabled="disabled||readonly||(max!==undefined&&modelValue>=max)" @click="update(modelValue+step)"><Plus :size="16"/></button></div></template>
<style scoped>.hys-ui-number-sm{min-height:30px}.hys-ui-number-lg{min-height:44px}</style>
